import zipfile
import csv
import os

# Extract the data
with zipfile.ZipFile('inputs/gtfs/sample_city_gtfs.zip', 'r') as z:
    z.extractall('/tmp/gtfs_extract/')

# Read the files
with open('/tmp/gtfs_extract/stops.txt', 'r') as f:
    stops = {}
    for line in f:
        line = line.strip()
        if not line:
            continue
        parts = line.split(',')
        stop_id = parts[0]
        stop_name = parts[1]
        stop_lat = float(parts[2])
        stop_lon = float(parts[3])
        stops[stop_id] = {'stop_name': stop_name, 'stop_lat': stop_lat, 'stop_lon': stop_lon}

with open('/tmp/gtfs_extract/trips.txt', 'r') as f:
    trips = {}
    for line in f:
        line = line.strip()
        if not line:
            continue
        parts = line.split(',')
        trip_id = parts[0]
        arrival_time = parts[1]
        departure_time = parts[2]
        stop_id = parts[3]
        stop_sequence = parts[4]
        trips[trip_id] = {'arrival_time': arrival_time, 'departure_time': departure_time, 'stop_id': stop_id, 'stop_sequence': stop_sequence}

with open('/tmp/gtfs_extract/routes.txt', 'r') as f:
    routes = {}
    for line in f:
        line = line.strip()
        if not line:
            continue
        parts = line.split(',')
        route_id = parts[0]
        route_name = parts[1]
        routes[route_id] = route_name

with open('/tmp/gtfs_extract/stop_times.txt', 'r') as f:
    stop_times = {}
    for line in f:
        line = line.strip()
        if not line:
            continue
        parts = line.split(',')
        trip_id = parts[0]
        arrival_time = parts[1]
        departure_time = parts[2]
        stop_id = parts[3]
        stop_sequence = parts[4]
        stop_times[stop_id] = {'departure_time': departure_time}

# Read clean stops
with open('/tmp/gtfs_extract/stops.txt', 'r') as f:
    for line in f:
        line = line.strip()
        if not line:
            continue
        parts = line.split(',')
        stop_id = parts[0]
        stop_name = parts[1]
        stop_lat = float(parts[2])
        stop_lon = float(parts[3])
        stops[stop_id] = {'stop_name': stop_name, 'stop_lat': stop_lat, 'stop_lon': stop_lon}

# Now process to count departures, routes, etc.
# We need to count stop_times per stop_id and join with trips to get route_ids

# First, let's read the stop_times properly
with open('/tmp/gtfs_extract/stop_times.txt', 'r') as f:
    for line in f:
        line = line.strip()
        if not line:
            continue
        parts = line.split(',')
        trip_id = parts[0]
        arrival_time = parts[1]
        departure_time = parts[2]
        stop_id = parts[3]
        stop_sequence = parts[4]

        if stop_id not in stop_times:
            stop_times[stop_id] = {'departure_time': departure_time}
        else:
            stop_times[stop_id]['departure_time'] = departure_time

# Now read trips to get route_id
with open('/tmp/gtfs_extract/trips.txt', 'r') as f:
    for line in f:
        line = line.strip()
        if not line:
            continue
        parts = line.split(',')
        trip_id = parts[0]
        arrival_time = parts[1]
        departure_time = parts[2]
        stop_id = parts[3]
        stop_sequence = parts[4]

        if trip_id not in trips:
            trips[trip_id] = {'arrival_time': arrival_time, 'departure_time': departure_time, 'stop_id': stop_id, 'stop_sequence': stop_sequence}

# Now read routes to get route_id
with open('/tmp/gtfs_extract/routes.txt', 'r') as f:
    for line in f:
        line = line.strip()
        if not line:
            continue
        parts = line.split(',')
        route_id = parts[0]
        route_name = parts[1]

        # We need to find which trip this route_id belongs to
        # Let's check the trips file for the route_id
        for trip_id, trip in trips.items():
            if trip['stop_id'] == stop_id:
                if route_id in trip:
                    trip['route_id'] = route_id
                break

# Now count departures and routes per stop
stop_counts = {}
for stop_id, stop in stops.items():
    # Count departures
    departures = 0
    for stop_id, stop_time in stop_times.items():
        if stop_time['departure_time']:
            departures += 1
    # Count routes
    routes = set()
    for stop_id, stop in stops.items():
        for stop_id, stop_time in stop_times.items():
            if stop_time['departure_time']:
                # Find the route_id for this stop
                for trip_id, trip in trips.items():
                    if trip['stop_id'] == stop_id:
                        trip['route_id'] = trip_id
                        break
                if trip_id in stop_times:
                    routes.add(trip['route_id'])
    stop_counts[stop_id] = {'n_departures': departures, 'n_routes': len(routes)}

# Get first and last departure times
min_departure = float('inf')
max_departure = float('-inf')
for stop_id, stop in stops.items():
    for stop_id, stop_time in stop_times.items():
        if stop_time['departure_time']:
            dep = float(stop_time['departure_time'])
            if dep < min_departure:
                min_departure = dep
            if dep > max_departure:
                max_departure = dep

# Build output
output = []
for stop_id, stop in stops.items():
    output.append({
        'stop_id': stop_id,
        'stop_name': stop['stop_name'],
        'stop_lat': stop['stop_lat'],
        'stop_lon': stop['stop_lon'],
        'n_departures': stop_counts[stop_id]['n_departures'],
        'n_routes': stop_counts[stop_id]['n_routes'],
        'first_departure': min_departure,
        'last_departure': max_departure
    })

# Write output
with open('outputs/t06_stop_service_intensity.csv', 'w', newline='') as f:
    writer = csv.writer(f, quoting=csv.QUOTE_MINIMAL)
    writer.writerow(['stop_id', 'stop_name', 'stop_lat', 'stop_lon', 'n_departures', 'n_routes', 'first_departure', 'last_departure'])
    for row in output:
        writer.writerow([row['stop_id'], row['stop_name'], row['stop_lat'], row['stop_lon'], 
                         row['n_departures'], row['n_routes'], row['first_departure'], row['last_departure']])

print('Output written successfully')
"
"}

